/**
 * Display spectra for the factory wavetables.
 *
 * GENERATED by tools/dump_wavetable_spectra.cpp - do not edit.
 *
 * Harmonics rather than samples, so the display can synthesise the waveform
 * at whatever width its canvas is and redraw it when the warp changes.
 * Analysed back out of the generated tables, so what is drawn is what the
 * oscillator actually plays.
 *
 * Layout: 20 tables x 32 frames x 64 harmonics, each harmonic a magnitude byte (0..127) followed by a
 * phase byte (-127..127 mapping to -pi..pi).
 *
 * This is the FALLBACK, used by the browser preview and before the plugin
 * has answered. In the plugin the live table is fetched over the bridge.
 */

export const DISPLAY_TABLE_COUNT = 20;
export const DISPLAY_FRAME_COUNT = 32;
export const DISPLAY_HARMONIC_COUNT = 64;

export const DISPLAY_SPECTRA_BASE64 =
  '';
